"""Verify output generated by the packaged desktop acceptance scenarios."""

from __future__ import annotations

import argparse
from collections import Counter
import csv
from datetime import date, timedelta
from html.parser import HTMLParser
import json
from pathlib import Path
import platform
import queue
import sys
import tempfile
import threading
import time
import xml.etree.ElementTree as ET

from calendar_models import BatchCancelled
from generate import APP_VERSION, LAYOUT_LABELS, prepare_replay, validate_png, write_batch
from quote_library import QUOTE_CATEGORIES, QUOTE_DIRECTORY, builtin_quotes, display_attribution, normalize_quote_key
from batch_history import run_history_scan, scan_history


class PreviewLinks(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.links: Counter[tuple[str, str]] = Counter()

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        values = dict(attrs)
        target = values.get("href" if tag == "a" else "src")
        if tag in {"a", "img"} and target is not None:
            self.links[tag, target] += 1


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def verify_builtin_corpus() -> dict[str, dict[str, str]]:
    expected_counts = {"b": 111, "d": 2015, "h": 198, "k": 307}
    records_by_id: dict[str, dict[str, object]] = {}
    for category, expected_count in expected_counts.items():
        source_path = QUOTE_DIRECTORY / f"{category}.json"
        records = json.loads(source_path.read_text(encoding="utf-8"))
        require(len(records) == expected_count, f"Unexpected upstream record count: {source_path.name}.")
        require(all(record.get("type") == category for record in records), f"Unexpected category in {source_path.name}.")
        records_by_id.update({record["uuid"]: record for record in records})

    quotes = builtin_quotes()
    require(len(quotes) >= 365, "The built-in corpus cannot fill a year without repeating a quote.")
    for quote in quotes:
        record = records_by_id.get(quote["quote_id"])
        require(record is not None, "A built-in quote UUID is missing from the pinned upstream files.")
        require(quote["quote"] == record["hitokoto"].strip(), "A built-in quote differs from its upstream text.")
        require(quote["source"] == display_attribution(record["from"], record.get("from_who")), "A built-in quote has a modified attribution.")
        require(bool(quote["source"]), "A built-in quote is missing a display attribution.")
        require(len(quote["quote_id"]) == 36 and quote["quote_id"].count("-") == 4, "A built-in quote is missing its upstream UUID.")
    return {quote["quote_id"]: quote for quote in quotes}


def verify_output(root: Path, *, full_year: bool) -> int:
    outputs = list(root.iterdir())
    require(len(outputs) == 1 and outputs[0].is_dir(), "Expected one batch and no leftover staging files.")
    batch = outputs[0]
    with (batch / "manifest.csv").open(encoding="utf-8-sig", newline="") as manifest:
        rows = list(csv.DictReader(manifest))
    start = date(2028, 1, 1) if full_year else date(2027, 1, 1)
    end = date(2028, 12, 31) if full_year else start
    count = (end - start).days + 1
    require(len(rows) == count, f"Expected {count} manifest rows; got {len(rows)}.")
    links = PreviewLinks()
    links.feed((batch / "index.html").read_text(encoding="utf-8"))
    links.close()
    expected_links = Counter({("a", "manifest.csv"): 1})
    basenames = set()
    quote_keys = set()
    quote_ids = set()
    builtin_by_id = verify_builtin_corpus()
    layouts = set()
    previous_layout = None
    for offset, row in enumerate(rows):
        day = start + timedelta(days=offset)
        iso_year, iso_week, _ = day.isocalendar()
        layout = row["layout"]
        require(row["date"] == day.isoformat(), f"Unexpected or missing date: {day}.")
        require(int(row["iso_week_year"]) == iso_year and int(row["iso_week"]) == iso_week, f"Incorrect ISO week: {day}.")
        require(row["layout_selection"] == ("random" if full_year else "A"), f"Incorrect layout selection: {day}.")
        require(layout in LAYOUT_LABELS and (layout != previous_layout if full_year else layout == "A"), f"Incorrect layout: {day}.")
        require(row["seed"] == "31415" and row["app_version"] == APP_VERSION and bool(row["python_version"]), f"Incorrect build metadata: {day}.")
        key = normalize_quote_key(row["quote"])
        quote_id = row["quote_id"].strip()
        require(bool(key and quote_id and row["source"].strip()) and key not in quote_keys and quote_id not in quote_ids, f"Missing or duplicate quote: {day}.")
        builtin = builtin_by_id.get(quote_id)
        require(builtin is not None and row["quote"] == builtin["quote"] and row["source"] == builtin["source"], f"Unexpected built-in quote: {day}.")
        quote_keys.add(key)
        quote_ids.add(quote_id)
        layouts.add(layout)
        previous_layout = layout
        basename = f"{day}_layout-{layout}"
        basenames.add(basename)
        svg = f"svg/{basename}.svg"
        png = f"png/{basename}.png"
        require(ET.parse(batch / svg).getroot().tag == "{http://www.w3.org/2000/svg}svg", f"Invalid SVG root: {svg}.")
        validate_png(batch / png)
        expected_links["a", svg] += 1
        expected_links["a", png] += 2
        expected_links["img", png] += 1

    if full_year:
        require(layouts == set(LAYOUT_LABELS), "Year batch did not exercise all nine layouts.")
    for suffix in ("svg", "png"):
        folder = batch / suffix
        require({item.name for item in folder.iterdir()} == {f"{name}.{suffix}" for name in basenames}, f"Unexpected files in {folder}.")
    require(links.links == expected_links, "Preview links do not match the manifest and generated files.")
    history = list(scan_history(root))
    require(len(history) == 1, "History did not discover the generated batch.")
    summary = history[0]
    require(not summary.error and len(summary.pages) == count and summary.seed == 31415,
            "History content differs from the batch manifest.")
    require(summary.has_preview and summary.missing_png == 0 and summary.missing_svg == 0,
            "History did not recognize the generated batch files.")
    cancelled = threading.Event()
    cancelled.set()
    history_events = queue.Queue()
    run_history_scan(root, cancelled, history_events)
    require(history_events.get_nowait() == ("cancelled", None) and history_events.empty(),
            "History cancellation leaked a batch result.")
    return count


def report_output_success(count: int) -> None:
    print(f"Portable desktop acceptance passed: {count} pages, SVG/PNG (1122 x 1402), manifest and preview links.", flush=True)


def check_output(output: Path, *, full_year: bool) -> int:
    try:
        count = verify_output(output, full_year=full_year)
    except (OSError, ValueError, RuntimeError, KeyError, TypeError, ET.ParseError, csv.Error) as exc:
        print(f"Desktop acceptance failed: {exc}", file=sys.stderr)
        return 1
    report_output_success(count)
    return 0


def verify_replay(output: Path, scratch: Path) -> None:
    batch = next(output.iterdir())
    manifest = batch / "manifest.csv"
    original_manifest = manifest.read_bytes()
    pages, seed = prepare_replay(manifest)
    page = pages[0]
    filename = f"{page.target_date.isoformat()}_layout-{page.layout}"
    original_svg = (batch / "svg" / f"{filename}.svg").read_bytes()
    original_png = (batch / "png" / f"{filename}.png").read_bytes()

    cancel_requested = False

    def request_cancel(completed: int, total: int) -> None:
        nonlocal cancel_requested
        cancel_requested = completed == total

    def check_cancel() -> None:
        if cancel_requested:
            raise BatchCancelled()

    restored = scratch / "日历 恢复"
    try:
        write_batch([page], restored, seed=seed, on_progress=request_cancel, check_cancel=check_cancel)
    except BatchCancelled:
        require(cancel_requested, "Replay cancelled before rendering the sample page.")
    else:
        raise ValueError("Replay was published despite cancellation.")
    require(set(scratch.iterdir()) == {output}, "Cancelled replay left staging files or a published batch.")

    write_batch([page], restored, seed=seed, on_progress=lambda completed, total: None)
    restored_pages, restored_seed = prepare_replay(restored / "manifest.csv")
    require(restored_pages == [page] and restored_seed == seed, "Replayed sample differs from the original manifest.")
    require((restored / "svg" / f"{filename}.svg").read_bytes() == original_svg, "Replayed SVG differs from the original.")
    validate_png(restored / "png" / f"{filename}.png")
    require(
        manifest.read_bytes() == original_manifest
        and (batch / "svg" / f"{filename}.svg").read_bytes() == original_svg
        and (batch / "png" / f"{filename}.png").read_bytes() == original_png,
        "Replay changed files in the original batch.",
    )


def verify_portable(*, full_year: bool) -> int:
    from desktop import run

    print(f"CalendarWorkflow {APP_VERSION} | {platform.platform()} | Python runtime {platform.python_version()}", flush=True)
    try:
        with tempfile.TemporaryDirectory(prefix="calendar-acceptance-") as scratch:
            scratch_root = Path(scratch)
            output = scratch_root / "日历 验收"
            exit_code = run(smoke_output=output, smoke_year=full_year)
            if exit_code:
                return exit_code
            count = verify_output(output, full_year=full_year)
            verify_replay(output, scratch_root)
            verify_manual_workflow(scratch_root)
            verify_multilayout_workflow(scratch_root)
            verify_random_workflow(scratch_root)
    except (OSError, ValueError, RuntimeError, KeyError, TypeError, ET.ParseError, csv.Error) as exc:
        print(f"Portable acceptance failed: {exc}", file=sys.stderr)
        return 1
    report_output_success(count)
    print("Nine layout examples and first-page preview/export PNG consistency passed.", flush=True)
    print("Sample manifest replay, cancellation cleanup and retry passed.", flush=True)
    print("History discovery, manifest summary and independent cancellation passed.", flush=True)
    print("Manual desktop preview/export consistency, blank/source-only nine-layout output and lossless replay passed.", flush=True)
    print("Multiple-layout desktop corpus/manual exports, same-day quotes and screenshot regression passed.", flush=True)
    print("Fully random defaults, per-date quantity, all-page preview/export and searchable quotation picker passed.", flush=True)
    return 0


def verify_multilayout_workflow(scratch: Path) -> None:
    from desktop import run
    from launcher import plan_pages

    for manual in (False, True):
        output = scratch / f"multi-layout-desktop-{int(manual)}"
        require(run(smoke_output=output, smoke_manual=manual, smoke_layouts="A+C+F") == 0,
                "Multiple-layout desktop preview/export failed.")
        batches = list(scan_history(output))
        require(len(batches) == 1 and batches[0].status == "文件齐全", "Multiple-layout history is incomplete.")
        pages = list(batches[0].pages)
        require([page.layout for page in pages] == ["A", "C", "F"], "Selected layouts were skipped or reordered.")
        require(len({(page.target_date, page.quote, page.source, page.quote_id) for page in pages}) == 1,
                "Same-day layouts did not share their quote and attribution.")
        for page in pages:
            validate_png(batches[0].directory / "png" / f"{page.target_date}_layout-{page.layout}.png")
    quote = next(item for item in builtin_quotes() if item["quote"].startswith("我们不能轻易将"))
    pages = plan_pages([date(2026, 11, 28)], [quote], "+".join(LAYOUT_LABELS), 17)
    batch = scratch / "screenshot-nine-layouts"
    write_batch(pages, batch, seed=17, on_progress=lambda *_: None)
    require(prepare_replay(batch / "manifest.csv") == (pages, 17), "Multiple-layout screenshot replay differs.")
    for page in pages:
        validate_png(batch / "png" / f"{page.target_date}_layout-{page.layout}.png")


def verify_random_workflow(scratch: Path) -> None:
    from PySide6.QtWidgets import QApplication
    from desktop import run
    from launcher import plan_pages
    from quote_picker_dialog import QuotePickerDialog
    from quote_selection import QuoteSearch

    output = scratch / "random-five-desktop"
    require(run(smoke_output=output, smoke_random_count=5, smoke_layouts="A") == 0,
            "Random per-date desktop workflow failed.")
    history = list(scan_history(output))
    require(len(history) == 1 and history[0].status == "文件齐全", "Random output history differs.")
    batch = history[0]
    require(len(batch.pages) == 5 and [page.variant for page in batch.pages] == [1, 2, 3, 4, 5],
            "Random per-date page count or ordinal differs.")
    require(len({page.quote for page in batch.pages}) == 5 and all(page.layout == "A" for page in batch.pages),
            "Random pool or distinct quotation contract differs.")
    gallery = (batch.directory / "index.html").read_text(encoding="utf-8")
    for page in batch.pages:
        validate_png(batch.directory / "png" / f"{page.basename}.png")
        require(f"png/{page.basename}.png" in gallery, "Random variant gallery link is missing.")
    pages, seed = prepare_replay(batch.directory / "manifest.csv")
    require(tuple(pages) == batch.pages and seed == batch.seed, "Random variant replay differs.")
    quotes = builtin_quotes()
    dialog = QuotePickerDialog(quotes, date(2026, 11, 27), ("A", "B"), "", None)
    try:
        require(len(dialog.records) == 5, "Default quotation recommendations must contain five candidates.")
        dialog.query.setText("苏轼 明月")
        dialog.show()
        deadline = time.monotonic() + 15
        while not dialog.use_button.isEnabled() and time.monotonic() < deadline:
            QApplication.processEvents()
            time.sleep(0.02)
        require(dialog.use_button.isEnabled(), f"Quotation picker preview failed: {dialog.preview_status.text()}")
        require(dialog.records == QuoteSearch(quotes).search("苏轼 明月"), "Quotation search scope differs.")
        record = dict(dialog.records[dialog.list.currentRow()])
        dialog.use_button.click()
        require(dialog.selected_quote == record, "Quotation confirmation changed the original record.")
        chosen = plan_pages([date(2026, 11, 27)], quotes, "A+B", selected_quote=record)
        require(len(chosen) == 2 and all(page.quote_id == record["quote_id"] and page.quote == record["quote"]
                                        and page.source == record["source"] for page in chosen),
                "Chosen quotation was not preserved across layouts.")
    finally:
        dialog.reject()
        dialog.deleteLater()
        QApplication.processEvents()


def verify_manual_workflow(scratch: Path) -> None:
    """Exercise packaged imports, the actual manual desktop path and nine PNGs."""
    from content_sources import ManualQuoteError, ManualQuoteSource, plan_manual_page
    from desktop import run

    output = scratch / "manual-desktop"
    require(run(smoke_output=output, smoke_manual=True) == 0, "Manual desktop smoke failed.")
    batches = list(scan_history(output))
    require(len(batches) == 1 and not batches[0].error, "Manual batch not recognized by history.")
    batch = batches[0]
    require(len(batch.pages) == 1 and batch.manifest_updated != "未知", "Manual history details missing.")
    page = batch.pages[0]
    require(page.quote == '春风又绿江南岸\n明月 <日常> & "文字"'
            and page.source == page.quote_id == "", "Manual draft was changed or corpus UUID leaked.")
    require(batch.seed == 31415 and batch.status == "文件齐全", "Manual batch metadata differs.")
    manual = ManualQuoteSource(page.quote)
    pages = [plan_manual_page(page.target_date, manual, layout, 31415).pages[0] for layout in LAYOUT_LABELS]
    nine = scratch / "manual-nine-layouts"
    write_batch(pages, nine, seed=31415, on_progress=lambda *_: None)
    restored, seed = prepare_replay(nine / "manifest.csv")
    require(restored == pages and seed == 31415, "Manual multiline replay was not lossless.")
    for candidate in pages:
        validate_png(nine / "png" / f"{candidate.target_date}_layout-{candidate.layout}.png")
    long_content = ManualQuoteSource("\n".join(["春风又绿江南岸"] * 5))
    for sample_seed in range(4):
        chosen = plan_manual_page(page.target_date, long_content, "RANDOM", sample_seed)
        require(chosen.pages[0].layout in "AE", "Random manual layout did not filter overflowing templates.")
    try:
        plan_manual_page(page.target_date, ManualQuoteSource("\n".join(["春"] * 6)), "RANDOM", 17)
    except ManualQuoteError:
        pass
    else:
        raise ValueError("Manual planner accepted a quote overflowing every template.")
    blank_output = scratch / "manual-blank-desktop"
    require(run(smoke_output=blank_output, smoke_manual=True, smoke_quote="") == 0,
            "Blank manual desktop preview/export failed.")
    blank_history = list(scan_history(blank_output))
    require(len(blank_history) == 1 and blank_history[0].status == "文件齐全",
            "Blank desktop batch could not be restored by history.")
    require(blank_history[0].pages[0].quote == blank_history[0].pages[0].source == "",
            "Blank desktop content changed.")
    for index, source in enumerate(("", "原样署名")):
        blanks = [plan_manual_page(page.target_date + timedelta(days=offset),
                                  ManualQuoteSource("\n\t ", source), layout, 31415).pages[0]
                  for offset, layout in enumerate(LAYOUT_LABELS)]
        blank_batch = scratch / f"manual-blank-{index}"
        write_batch(blanks, blank_batch, seed=31415, on_progress=lambda *_: None)
        blank_pages, blank_seed = prepare_replay(blank_batch / "manifest.csv")
        require(blank_pages == blanks and blank_seed == 31415,
                "Blank/source-only manual content did not round-trip through the manifest.")
        for blank in blanks:
            validate_png(blank_batch / "png" / f"{blank.target_date}_layout-{blank.layout}.png")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    parser.add_argument("--full-year", action="store_true")
    args = parser.parse_args()
    return check_output(args.output, full_year=args.full_year)


if __name__ == "__main__":
    raise SystemExit(main())
